import React from "react";

export default function Gallery(){
  const imgs = [
    "https://www.gipsm.in/images/banner1.jpg",
    "https://www.gipsm.in/images/banner2.jpg",
    "https://www.gipsm.in/images/images1.jpg",
  ];
  return (
    <div className="container">
      <div className="card">
        <h2 style={{color:"#005baa"}}>Gallery</h2>
        <div style={{display:"flex",gap:12,flexWrap:"wrap",marginTop:12}}>
          {imgs.map((s,i)=> <img key={i} src={s} style={{width:320,height:180,objectFit:"cover",borderRadius:6}} alt={`g${i}`}/>)}
        </div>
      </div>
    </div>
  );
}
